Given two sorted arrays a[] and b[] with distinct elements, the task is to return union of both the arrays in sorted order.Note: Union of two arrays is an array having all distinct elements that are present in either array.Examples:Input: a[] = {1, 2, 3}, b[] = {2, 5, 7}Output: {1, 2, 3, 5, 7}Explanation: 1, 2, 3, 5 and 7 are the distinct elements present in either array.Input: a[] = {2, 4, 5}, b[] = {1, 2, 3, 4, 5}Output: {1, 2, 3, 4, 5}Explanation: 1, 2, 3, 4 and 5 are the distinct elements present in either array.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) Space[Better Approach 1] Using Set - O((n+m)*log(n+m)) Time and O(n+m) Space[Better Approach 2] Using Binary Search - O((n+m)*log(n+m)) Time and O(1) Space[Expected Approach] Using Merge Step of Merge Sort - O(n+m) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to add all elements from the first array a[] to result array. Then, iterate through the second array b[] and add its elements to the result only if they were not present in a[]. Finally, sort the result array to get the union in sorted order.
            C++

    // C++ program to find union of two sorted arrays 
// with distinct elements using nested loops

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

vector<int> findUnion(vector<int> &a, vector<int> &b) {
    int n = a.size(), m = b.size();
    vector<int> res = a;

    // Traverse through b[] and search every element
    // b[i] in a[]
    for (int i = 0; i < m; i++) {

        // check if the element is already in the
        // result to avoid duplicates
        int j;
        for (j = 0; j < n; j++) {
            if (a[j] == b[i])
                break;
        }

        // if not already present in a[] then
        // add it to result
        if (j == n) {
            res.push_back(b[i]);
        }
    }
  	sort(res.begin(), res.end());
    return res;
}

int main() {

    vector<int> a = {1, 2, 3};
    vector<int> b = {2, 5, 7};

    vector<int> res = findUnion(a, b);

    for (int i = 0; i < res.size(); i++)
        cout << res[i] << " ";

    return 0;
}


