#include <stdio.h>

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int* findUnion(int *a, int n, int *b, int m, int *resSize) {
    int *res = (int *)malloc((n + m) * sizeof(int));
    int k = 0;

    // Copy elements of a[] to result
    for (int i = 0; i < n; i++) {
        res[k++] = a[i];
    }

    // Traverse through b[] and search every element
    // b[i] in a[]
    for (int i = 0; i < m; i++) {

        // Check if the element is already in the result
        // to avoid duplicates
        int j;
        for (j = 0; j < n; j++) {
            if (a[j] == b[i])
                break;
        }

        // If not already present then add it to result
        if (j == n) {
            res[k++] = b[i];
        }
    }

    // Resize the result array
    res = (int *)realloc(res, k * sizeof(int));
    *resSize = k;

    qsort(res, *resSize, sizeof(int), compare);

    return res;
}

int main() {
    int a[] = {1, 2, 3};
    int b[] = {2, 5, 7};
    int resSize;

    int *res = findUnion(a, 3, b, 3, &resSize);

    for (int i = 0; i < resSize; i++)
        printf("%d ", res[i]);
