// Function to perform binary search
int binarySearch(vector<int> &arr, int lo, int hi, int target) {
    while (lo <= hi){
        int mid = lo + (hi - lo) / 2;

        if (arr[mid] == target)
            return mid;
        if (arr[mid] < target)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return -1;
}

